<template>
  <section id="agent-interactions" class="interaction-section">
    <header class="graph-heading">
      <div><p class="eyebrow">Inside the analysis</p><h2>{{ initiallyCollapsed?'Explore the full interaction network.':'See who is interacting.' }}</h2></div>
      <button class="quiet-button" :aria-expanded="!collapsed" aria-controls="interaction-body" @click="collapsed=!collapsed">{{ collapsed ? 'Show diagram' : 'Hide diagram' }}</button>
    </header>
    <div v-show="!collapsed" id="interaction-body">
      <p class="graph-intro">Analysts and traders discuss the evidence. When the chart supports a virtual market, it also matches simulated orders. Select a node or connection to see what happened.</p>
      <p v-if="run.agent_lifecycle" class="graph-intro">Node status records request pending/in progress, saved output or failure at execution boundaries. Model requests share the configured model, including queue/validation; highlighted speech is not a working-state signal.</p><p v-if="view==='traders'" class="graph-intro">Trader identities share batched requests. Their labels describe saved message phases, not independent live processes.</p>
      <div class="graph-toolbar">
        <div class="view-tabs" role="group" aria-label="Interaction diagram view">
          <button :aria-pressed="view==='discussion'" @click="changeView('discussion')">Analyst discussion <span>{{ analysts.length }}</span></button>
          <button :aria-pressed="view==='traders'" @click="changeView('traders')">Trader conversations <span>{{ dialogue?.participant_count || '—' }}</span></button>
          <button :aria-pressed="view==='market'" @click="changeView('market')">Virtual market <span>{{ population?.status==='complete' ? population.participant_count : '—' }}</span></button>
        </div>
        <button class="quiet-button" @click="resetPositions">Reset positions</button>
        <label v-if="view==='discussion'" class="check-control"><input v-model="showData" type="checkbox"> Show data flow</label>
        <template v-else-if="view==='market' && population?.status==='complete'">
          
          <label v-if="expand" class="case-control">Connections<select v-model="marketMode"><option value="counterparties">Matched counterparties</option><option value="orders">Orders through exchange</option></select></label>
          <label class="case-control">Liquidity case<select v-model="selectedCase"><option v-for="item in population.scenarios" :key="item.id" :value="item.id">{{ item.name }}</option></select></label>
        </template>
        <label v-if="view==='traders'&&dialogue?.shared_views?.length" class="case-control">Exchange<select v-model="traderRound"><option value="cross_group">Across trading styles</option><option value="paired">Initial paired exchange</option></select></label>
      </div>
      <p class="graph-status" role="status"><span :class="['status-dot',{running:isPendingAnalysis(run.status)}]"></span>{{ statusText }}</p>
      <p v-if="view==='traders'&&dialogue" class="graph-footnote">{{ dialogue.method }} {{ dialogue.changed_decisions || 0 }} decisions revised · {{ dialogue.changed_stances || 0 }} directional views changed.</p>
      <div v-if="view==='traders'&&dialogue?.status==='incomplete'" class="match-status"><p>Some messages could not be validated. Completed conversations and memories are preserved; the market does not use incomplete discussion.</p><button class="quiet-button" :disabled="isPendingAnalysis(run.status)||resuming" @click="emit('resume-traders')">{{ resuming ? 'Resuming saved messages…' : isPendingAnalysis(run.status) ? 'Wait for this analysis to finish' : 'Resume missing trader messages' }}</button></div>
      <div v-if="view==='traders'&&dialogue?.status==='complete'&&(dialogue.peer_count||1)<3" class="match-status"><p>This report has the initial paired discussion. Add an exchange with three different trading styles per trader using its saved views.</p><button class="quiet-button" :disabled="isPendingAnalysis(run.status)||resuming" @click="emit('resume-traders')">{{ resuming ? 'Starting wider discussion…' : 'Add cross-group discussion' }}</button></div>
      <div v-if="view==='traders'&&dialogue?.status==='complete'&&dialogue.peer_count>=3" class="perspective-coverage" role="status"><strong>{{ run.trader_review?.reviewed_count || 0 }} / {{ dialogue.participant_count }} final perspectives reviewed</strong><p>{{ run.verdict?.trader_view_coverage ? 'Every final thesis and individual review was supplied to the final assessment. Select a trader to inspect how its argument was treated.' : run.trader_review?.status==='complete' ? 'All perspectives are reviewed and ready for the final assessment.' : 'Each trader receives an individual evidence review, including opposing, waiting, and execution-focused views. The final assessment requires full coverage.' }}</p><button v-if="!isPendingAnalysis(run.status)&&(!run.verdict?.trader_view_coverage||run.trader_review?.status!=='complete')" class="quiet-button" :disabled="resuming" @click="emit('resume-traders')">{{ resuming ? 'Continuing saved analysis…' : run.trader_review?.status==='complete' ? 'Complete final assessment' : run.trader_review?.reviewed_count ? 'Continue perspective review' : 'Review every trader perspective' }}</button></div>
      <div v-if="view==='traders' && dialogue || view==='market' && expand && population?.status==='complete'" class="individual-controls"><p>Each node is one trader. Drag to arrange; click to inspect its conversations. Arrow keys move a focused node.</p><div><button class="quiet-button" aria-label="Zoom out diagram" :disabled="zoom<=1" @click="zoom=Math.max(1,zoom-.5)">−</button><span>{{ zoom*100 }}%</span><button class="quiet-button" aria-label="Zoom in diagram" :disabled="zoom>=2.5" @click="zoom=Math.min(2.5,zoom+.5)">+</button></div></div>
      <p v-if="view==='market' && expand && marketMode==='counterparties'" class="match-status" aria-live="polite">{{ matchStatus }} <button v-if="matchError" class="quiet-button" @click="fetchMatches">Retry connections</button></p>
      <div v-if="view==='market' && population?.status!=='complete'" class="graph-empty"><h3>{{ isPendingAnalysis(run.status) && !population ? 'The virtual market follows the opening views.' : 'No virtual market recorded for this analysis.' }}</h3><p>{{ population?.reason || (isPendingAnalysis(run.status) ? 'The diagram will appear when the simulated orders and fills have been computed.' : 'Reanalyse these charts to include the current participant model.') }}</p></div>
      <div v-else-if="view==='traders'&&!dialogue" class="graph-empty"><h3>{{ isPendingAnalysis(run.status) ? 'Trader conversations follow the analyst openings.' : 'No trader conversations were recorded in this report.' }}</h3><p>{{ run.population?.reason || (isPendingAnalysis(run.status) ? 'Each trader will form a view, challenge a peer and reply before the market simulation runs.' : 'Reanalyse these charts to include the new conversation layer. Existing reports keep their original results.') }}</p><template v-if="!isPendingAnalysis(run.status)&&run.version>=6&&run.observation?.is_chart&&run.opinions?.length"><p>{{ run.opinions.length }} specialist opening views were saved. Resume to finish any missing specialist views and continue the trader discussion.</p><button class="quiet-button" :disabled="resuming" @click="emit('resume-traders')">{{ resuming ? 'Resuming saved work…' : 'Resume saved analysis' }}</button></template></div>
      <template v-else>
        <div class="network-layout">
          <div class="network-canvas">
            <div class="network-scroll" tabindex="0" aria-label="Scrollable agent interaction diagram">
              <svg viewBox="0 0 920 650" class="network" :class="{'individual-network':view==='traders'||view==='market'&&expand}" :style="view==='traders'||view==='market'&&expand?{width:zoom*100+'%'}:null" role="group" :aria-label="view==='discussion' ? 'Analyst questions and replies' : view==='traders' ? 'Virtual trader questions and replies' : 'Virtual traders and exchange connections'">
                <defs><marker v-for="kind in arrowKinds" :id="'agent-arrow-'+kind" :key="kind" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L8 4L0 8Z" :fill="edgeColors[kind]"/></marker></defs>
                <g v-for="edge in graph.edges" :key="edge.id" class="graph-edge" :class="{chosen:selection===edge.id}" :style="{opacity:edgeOpacity(edge)}" role="button" :tabindex="expand && view==='market' ? -1 : 0" :aria-label="edgeName(edge)" @click="selection=edge.id" @keydown.enter.prevent="selection=edge.id" @keydown.space.prevent="selection=edge.id">
                  <title>{{ edgeName(edge) }}</title>
                  <path :d="edge.path" class="edge-hit"/>
                  <path :d="edge.path" class="edge-line" :stroke="edgeColors[edge.kind]" :stroke-dasharray="['data','membership','shared_view'].includes(edge.kind)?'3 5':null" :marker-end="edge.kind==='membership'?null:'url(#agent-arrow-'+edge.kind+')'"/>
                </g>
                <g v-for="node in graph.nodes" :key="node.id" :transform="`translate(${node.x},${node.y})`" class="graph-node" :class="{chosen:selection===node.id,trader:node.type==='trader',dragging:dragging===node.id}" :style="{opacity:nodeOpacity(node)}" role="button" :tabindex="0" :data-agent-id="node.id" :aria-pressed="selection===node.id" :aria-label="node.label+(node.status ? ' · '+node.status : '')" @click="activate($event,node,selectNode)" @pointerdown="startDrag($event,node)" @touchstart.prevent @pointermove="moveDrag" @pointerup="finishDrag($event,false,selectNode)" @pointercancel="finishDrag($event,true)" @lostpointercapture="finishDrag($event,true)" @keydown="nudge($event,node)" @keydown.enter.prevent="selection=node.id" @keydown.space.prevent="selection=node.id">
                  <title>{{ node.label }}{{ node.status ? ' · '+node.status : '' }}</title>
                  <circle class="node-halo" :r="nodeRadius(node)+7"/>
                  <circle class="node-disc" :r="nodeRadius(node)" :fill="nodeColor(node)"/>
                  <text v-if="node.type!=='trader'||readableTraders" class="node-symbol" text-anchor="middle" y="4">{{ node.type==='trader'?node.number:nodeSymbol(node) }}</text>
                  <text v-if="node.type!=='trader'" class="node-label" text-anchor="middle"><tspan v-for="(line,i) in nodeLines(node)" :key="i" x="0" :y="33+i*13">{{ line }}</tspan></text>
                  <text v-else-if="readableTraders||selection===node.id" class="node-label" text-anchor="middle" :y="readableTraders?nodeRadius(node)+18:-15">{{ readableTraders?`Trader ${String(node.number).padStart(2,'0')}`:node.label }}</text>
                </g>
              </svg>
            </div>
            <div class="graph-legend" v-if="view!=='market'"><span v-if="view==='traders'&&traderRound==='cross_group'&&dialogue?.shared_views?.length"><i class="dotted-key"></i>Shared view →</span><span v-else><i class="line-key" style="background:#bb581e"></i>Question →</span><span><i class="line-key" style="background:#356fa5"></i>Reply →</span><span v-if="view==='discussion'&&showData"><i class="dotted-key"></i>Data input →</span><span><i class="dot-key bullish"></i>Bullish</span><span><i class="dot-key bearish"></i>Bearish</span><span><i class="dot-key neutral"></i>Mixed / waiting</span></div>
            <div class="graph-legend" v-else-if="expand&&marketMode==='counterparties'"><span><i class="line-key" style="background:#347e70"></i>Buyer → seller</span><span>One node per trader · matched through the virtual exchange</span></div>
            <div class="graph-legend" v-else><span v-if="expand"><i class="line-key" style="background:#a077b7"></i>Orders / quotes →</span><span><i class="line-key" style="background:#347e70"></i>Computed fills →</span></div>
          </div>
          <aside class="graph-inspector">
            <label for="inspect-interaction">Inspect an interaction</label>
            <select id="inspect-interaction" v-model="selection"><option value="">Choose a node or connection</option><optgroup label="Agents and inputs"><option v-for="node in graph.nodes" :key="node.id" :value="node.id">{{ node.label }}</option></optgroup><optgroup v-if="graph.edges.length" label="Connections"><option v-for="edge in graph.edges" :key="edge.id" :value="edge.id">{{ edgeName(edge) }}</option></optgroup></select>
            <template v-if="selectedNode">
              <p class="inspector-kicker">{{ typeLabel(selectedNode.type) }}</p><h3>{{ selectedNode.label }}</h3>
              <p v-if="selectedNode.status" class="node-status">{{ selectedNode.status }}<span v-if="selectedNode.type==='analyst'"> · {{ stanceLabel(selectedNode.stance) }}</span></p>
              <template v-if="selectedNode.type==='analyst'">
                <p class="role-focus">{{ selectedNode.role.focus }}</p>
                <h4 v-if="selectedNode.opening">Opening view</h4><p>{{ selectedNode.opening?.thesis }}</p>
                <h4 v-if="selectedNode.reply">After discussion</h4><p>{{ selectedNode.reply?.revised_thesis }}</p>
                <p v-if="!selectedNode.opening" class="muted">This specialist has not returned a saved opening view yet.</p>
              </template>
              <template v-else-if="selectedNode.type==='trader'">
                <p>{{ selectedTraderGroup?.behavior }}</p>
                <TraderMemory v-if="view==='traders'&&dialogue" :dialogue="dialogue" :review="run.trader_review" :levels="run.observation?.levels || []" :actor-id="selectedNode.id" @inspect="selection=$event" />
                <details :open="view==='market'"><summary>Trading profile</summary><dl class="inspector-facts"><div><dt>Capital share</dt><dd>{{ (selectedNode.trader.capital_weight*100).toFixed(3) }}%</dd></div><div><dt>Information delay</dt><dd>{{ selectedNode.trader.information_delay }} rounds</dd></div><div><dt>Virtual leverage</dt><dd>{{ number(selectedNode.trader.leverage) }}×</dd></div><div><dt>Holding limit</dt><dd>{{ selectedNode.trader.holding_rounds }} rounds</dd></div></dl></details>
                <p v-if="view==='market'&&!selectedNode.flow" class="muted">Individual order totals were not recorded in this older report.</p>
              </template>
              <template v-else><p>{{ selectedNode.description }}</p><p v-if="selectedNode.group">{{ selectedNode.count }} traders · {{ (selectedNode.group.capital_share*100).toFixed(0) }}% of model trader capital.</p><p v-if="selectedNode.type==='moderator' && !run.verdict" class="muted">Combines the discussion, unresolved disagreement and scenario limits into the final conditional assessment.</p></template>
            </template>
            <template v-else-if="selectedEdge">
              <p class="inspector-kicker">{{ selectedEdge.label }}</p><h3>{{ nodeName(selectedEdge.source) }} → {{ nodeName(selectedEdge.target) }}</h3>
              <p v-if="selectedEdge.message?.peer_names" class="muted">This response is addressed to {{ selectedEdge.message.peer_names.join(', ') }}.</p>
              <template v-if="selectedEdge.kind==='question'"><blockquote>{{ selectedEdge.message.question }}</blockquote><h4 v-if="selectedEdge.message.why_it_matters">Why it matters</h4><p>{{ selectedEdge.message.why_it_matters }}</p><details v-if="selectedEdge.message.target_thesis"><summary>Original view being challenged</summary><p>{{ selectedEdge.message.target_thesis }}</p></details></template>
              <template v-else-if="selectedEdge.kind==='shared_view'"><blockquote>{{ selectedEdge.message.thesis }}</blockquote><p>{{ stanceLabel(selectedEdge.message.stance) }} · This saved view was shared from the earlier exchange, with its source retained. It is available in {{ nodeName(selectedEdge.target) }}’s inbox for the cross-group review.</p></template>
              <template v-else-if="selectedEdge.kind==='reply'"><blockquote>{{ selectedEdge.message.response }}</blockquote><h4>{{ stanceLabel(selectedEdge.message.stance) }} after discussion</h4><p>{{ selectedEdge.message.change_reason }}</p><h4 v-if="selectedEdge.message.remaining_disagreement">Still unresolved</h4><p>{{ selectedEdge.message.remaining_disagreement }}</p></template>
              <template v-else-if="selectedEdge.kind==='match'"><p>{{ nodeName(selectedEdge.source) }} bought from {{ nodeName(selectedEdge.target) }} through the simulated exchange.</p><dl class="inspector-facts"><div><dt>Model units</dt><dd>{{ number(selectedEdge.match.units) }}</dd></div><div><dt>Average fill price</dt><dd>{{ number(selectedEdge.match.average_price) }}</dd></div><div><dt>Rounds with a match</dt><dd>{{ selectedEdge.match.matched_rounds }}</dd></div><div><dt>First / last round</dt><dd>{{ selectedEdge.match.first_round }} / {{ selectedEdge.match.last_round }}</dd></div></dl><p class="muted">Path 1 of {{ graph.scenario.paths }} · {{ graph.scenario.name }}. This is the model’s pro-rata allocation, not trader chat or a real venue execution.</p><div class="counterparty-actions"><button class="quiet-button" @click="selection=selectedEdge.source">Inspect buyer</button><button class="quiet-button" @click="selection=selectedEdge.target">Inspect seller</button></div></template>
              <p v-else-if="selectedEdge.kind==='data'">{{ selectedEdge.label }}. This is an input connection, not a spoken message.</p>
              <p v-else-if="selectedEdge.kind==='membership'">This virtual trader belongs to {{ nodeName(selectedEdge.target) }}. A group connection describes its behavior rules.</p>
              <p v-else>Computed activity through the virtual exchange in the selected liquidity case. Orders are requests; fills are the volume that actually matched inside the model.</p>
            </template>
            <template v-else><p class="inspector-kicker">{{ view!=='market'?'Read the conversation':'Explore the population' }}</p><h3>{{ view!=='market'?'Follow the opposing case.':'Different rules, shared market.' }}</h3><p>{{ view==='traders'?'Click a trader to read its views, addressed messages and saved memory.':view==='discussion'?'Click an analyst for their role and view. Click an orange question or blue reply to read the actual message.':'Choose any individual trader to see its counterparties. Arrows point from the buyer to the seller; selecting a connection reveals its recorded matches.' }}</p><p class="muted">{{ view!=='market'?'Connections appear as messages are saved during analysis. A missing connection means that message is not recorded yet.':'Traders react through price, liquidity and positions. They do not exchange chat messages.' }}</p></template>
            <section v-if="counterparties.length" class="counterparty-list"><h4>{{ counterparties.length }} counterparties · path 1</h4><p class="muted">Amounts below are relative to {{ nodeName(focusId) }}. Select another trader to follow its connections.</p><button v-for="other in counterparties" :key="other.id" @click="selection=other.id"><strong>{{ nodeName(other.id) }}</strong><span>Bought {{ number(other.bought) }} · sold {{ number(other.sold) }}</span></button></section>
            <h4 v-if="selectedFlow && view==='market'">Totals across all {{ graph.scenario.paths }} paths</h4>
            <dl v-if="selectedFlow" class="inspector-facts"><div v-if="selectedFlow.order_submissions!=null"><dt>Order submissions</dt><dd>{{ number(selectedFlow.order_submissions) }}</dd></div><div v-if="selectedFlow.quote_updates!=null"><dt>Quote updates</dt><dd>{{ number(selectedFlow.quote_updates) }}</dd></div><div><dt>Model units bought</dt><dd>{{ number(selectedFlow.bought) }}</dd></div><div><dt>Model units sold</dt><dd>{{ number(selectedFlow.sold) }}</dd></div></dl>
            <div v-if="connections.some(edge=>edge.kind!=='match')" class="connection-list"><h4>Connected activity</h4><button v-for="edge in connections.filter(item=>item.kind!=='match')" :key="edge.id" @click="selection=edge.id">{{ edgeName(edge) }}</button></div>
          </aside>
        </div>
        <p class="graph-footnote" v-if="view==='market'">{{ expand&&marketMode==='counterparties' ? `Matched connections cover path 1 of ${graph.scenario.paths}, across ${population.clearing_rounds} clearing rounds in ${graph.scenario.name.toLowerCase()}.` : `Order activity is aggregated across ${graph.scenario.paths} paths and ${population.clearing_rounds} clearing rounds.` }} These are model events, not live market transactions.{{ matches?.provenance==='verified_replay'&&marketMode==='counterparties' ? ' Connections were recovered by an exact replay checked against every original archived array. The saved report is unchanged.' : '' }}</p>
        <p class="graph-footnote" v-else-if="view==='traders'">{{ dialogue.memory_scope }} Each question and reply shown here was saved by the discussion engine. {{ population?.status==='complete' ? 'Opening and revised policy controls are compared using the same numerical starting conditions.' : 'No numerical market comparison has been recorded for this chart.' }}</p>
        <p class="graph-footnote" v-else>Questions and replies are separate model calls using shared chart evidence. Agreement is not a calibrated probability.{{ inactiveCount ? ` ${inactiveCount} specialist roles lack the required inputs for this chart and are not shown as active nodes.` : '' }}</p>
      </template>
    </div>
  </section>
</template>

<script setup>
import {apiBase,apiFetch} from '../api/platform'
import {isPendingAnalysis} from '../utils/platform.mjs'
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {discussionGraph,marketGraph,traderConversationGraph,layoutGraph} from '../utils/agentGraph.mjs'
import TraderMemory from './TraderMemory.vue'
import {useGraphDrag} from '../utils/useGraphDrag.js'
const props=defineProps({run:{type:Object,required:true},caseId:{type:String,default:'1'},initialView:{type:String,default:'discussion'},initiallyCollapsed:Boolean,initialShowData:Boolean,resuming:Boolean})
const emit=defineEmits(['update:caseId','resume-traders'])
const view=ref(['market','traders'].includes(props.initialView)?props.initialView:'discussion'),collapsed=ref(props.initiallyCollapsed),showData=ref(props.initialShowData),expand=ref(true),selection=ref(''),zoom=ref(1)
const marketMode=ref('counterparties'),focusId=ref(''),matches=ref(null),matchesLoading=ref(false),matchError=ref('')
const traderRound=ref('cross_group')
const api=apiBase
const matchCache=new Map()
let matchController,matchRequest=0
const selectedCase=computed({get:()=>props.caseId,set:value=>emit('update:caseId',value)})
const population=computed(()=>props.run.population)
const dialogue=computed(()=>props.run.trader_dialogue)
const analysts=computed(()=>props.run.roster?.filter(role=>role.active)||[])
const inactiveCount=computed(()=>props.run.roster?.filter(role=>!role.active).length||0)
const {positions,dragging,startDrag,moveDrag,finishDrag,activate,nudge,resetPositions}=useGraphDrag(computed(()=>`${props.run.id}:network:${view.value}`))
const readableTraders=computed(()=>(view.value==='traders'?dialogue.value?.participant_count:population.value?.participant_count)<=60)
const nodeRadius=node=>node.type==='trader'?(readableTraders.value?18:5):18
const selectNode=id=>{selection.value=id}
const graph=computed(()=>layoutGraph(view.value==='discussion'?discussionGraph(props.run,{showData:showData.value}):view.value==='traders'?traderConversationGraph(dialogue.value,{round:traderRound.value}):marketGraph(population.value,selectedCase.value,expand.value,{mode:marketMode.value,matches:matches.value}),view.value,{individual:true,positions:positions.value}))
const selectedNode=computed(()=>graph.value.nodes.find(node=>node.id===selection.value))
const selectedEdge=computed(()=>graph.value.edges.find(edge=>edge.id===selection.value))
const connections=computed(()=>selectedNode.value?graph.value.edges.filter(edge=>edge.source===selection.value||edge.target===selection.value).filter(edge=>edge.kind!=='membership'):[])
const selectedTraderGroup=computed(()=>(view.value==='traders'?dialogue.value:population.value)?.cohorts.find(group=>group.id===selectedNode.value?.trader?.behavior))
const selectedFlow=computed(()=>selectedNode.value?.flow||selectedEdge.value?.flow||(selectedNode.value?.group?graph.value.scenario?.cohort_activity[selectedNode.value.group.family]:null))
const counterparties=computed(()=>{if(selectedNode.value?.id!==focusId.value||matches.value?.status!=='complete'||marketMode.value!=='counterparties')return [];const accounts=new Map();for(const pair of matches.value.matches){const buying=pair.buyer_id===focusId.value,id=buying?pair.seller_id:pair.buyer_id;if(!accounts.has(id))accounts.set(id,{id,bought:0,sold:0});accounts.get(id)[buying?'bought':'sold']+=pair.units}return [...accounts.values()].sort((a,b)=>b.bought+b.sold-a.bought-a.sold)})
const matchStatus=computed(()=>matchesLoading.value?'Loading matched counterparties…':matchError.value||matches.value?.reason||(matches.value?.status==='complete'?`${nodeName(focusId.value)} · ${matches.value.counterparty_count} counterparties · path 1 of ${matches.value.paths_in_case}`:'Select an individual trader to see its matched counterparties.'))
const statusText=computed(()=>view.value==='discussion'?`${props.run.opinions?.length||0} openings · ${props.run.challenges?.length||0} questions · ${props.run.replies?.length||0} replies${isPendingAnalysis(props.run.status)?' · '+props.run.stage:' · '+(props.run.status==='complete'?'Saved discussion':props.run.status)}`:view.value==='traders'?`${dialogue.value?.counts?.openings||0} views · ${dialogue.value?.counts?.questions||0} questions · ${dialogue.value?.counts?.replies||0} paired replies · ${dialogue.value?.counts?.cross_group_replies||0} cross-group responses · ${dialogue.value?.model_calls||0} batched calls`:population.value?.status==='complete'?`${population.value.participant_count} virtual traders · 1 external liquidity provider`:'Waiting for participant simulation')
const edgeColors={question:'#bb581e',reply:'#356fa5',shared_view:'#8a98a9',data:'#9aa0a6',membership:'#a7adb4',order:'#a077b7',fill:'#347e70',flow:'#347e70',match:'#347e70'}
const arrowKinds=Object.keys(edgeColors).filter(kind=>kind!=='membership')
const nodeName=id=>graph.value.nodes.find(node=>node.id===id)?.label||id
const edgeName=edge=>edge.kind==='match'?`${nodeName(edge.source)} buys from ${nodeName(edge.target)}`:`${edge.label}: ${nodeName(edge.source)} → ${nodeName(edge.target)}`
const number=value=>{const amount=Number(value||0);return amount!==0&&Math.abs(amount)<.001?amount.toPrecision(3):amount.toLocaleString('en-US',{maximumFractionDigits:6})}
const stanceLabel=value=>({bullish:'Bullish',bearish:'Bearish',mixed:'Mixed',no_setup:'No setup',pending:'Pending'}[value]||value)
const typeLabel=value=>({analyst:'Analyst agent',trader:'Virtual trader',cohort:'Behavior group',input:'Shared evidence',moderator:'Final synthesis',provider:'Virtual liquidity account',exchange:'Simulated matching',simulation:'Participant model'}[value]||value)
const shortNames={ict_liquidity:['ICT liquidity'],ict_fvg:['ICT fair-value gap'],ict_orderblocks:['ICT order blocks'],support_resistance:['Support &','resistance'],price_action:['Price action'],trend:['Trend following'],momentum:['Momentum'],mean_reversion:['Mean reversion'],overextension:['Overextension','& pullback'],potential_top:['Potential top'],potential_bottom:['Potential bottom'],volume:['Volume & auction'],order_flow:['Order flow'],derivatives:['Funding &','derivatives'],market_maker:['Market making'],relative_value:['Relative value'],classical:['Wyckoff & patterns'],quant:['Quant researcher'],macro:['Macro & news'],session:['Session behavior'],risk:['Risk & skeptic'],exchange:['Virtual exchange'],'chart-input':['Chart evidence'],moderator:['Moderator'],external_liquidity_provider:['Liquidity provider']}
const groupNames={market_maker:['Market makers'],trend:['Trend followers'],reversion:['Mean reversion'],breakout:['Breakout traders'],liquidity:['Level reactions'],noise:['Noise traders'],execution:['Large execution'],leveraged:['Leveraged traders']}
const nodeLines=node=>node.type==='simulation'?['Virtual market',node.status]:node.id==='chart-input'?[node.label]:node.type==='cohort'?[...(groupNames[node.group.id]||[node.label]),`${node.count} traders`]:shortNames[node.id]||[node.label]
const nodeColor=node=>node.type==='analyst'||node.type==='moderator'||node.dialogueAgent?({bullish:'#327e64',bearish:'#b55046',mixed:'#718094',no_setup:'#718094',pending:'#aab0b7'}[node.stance]||'#718094'):node.type==='trader'?'#647d88':node.type==='cohort'?'#456a78':node.type==='exchange'?'#333b43':'#77818b'
const nodeSymbol=node=>node.type==='analyst'?({bullish:'↑',bearish:'↓',mixed:'↔',no_setup:'·',pending:'…'}[node.stance]||'·'):node.type==='cohort'?node.count:node.type==='exchange'?'⇄':node.type==='moderator'?'M':node.type==='input'?'C':node.type==='simulation'?'V':'LP'
function defaultTrader(){const scenario=population.value?.scenarios?.find(item=>item.id===selectedCase.value)||population.value?.scenarios?.[0];const active=new Set(scenario?.actor_activity?.filter(item=>item.order_submissions>0).map(item=>item.id)||[]);return population.value?.participants?.find(item=>item.behavior==='trend'&&active.has(item.id))?.id||population.value?.participants?.[0]?.id||''}
let viewChosen=false
function changeView(value){viewChosen=true;view.value=value;selection.value=value==='traders'?dialogue.value?.participants?.[0]?.id||'':value==='market'&&expand.value?defaultTrader():''}
function edgeOpacity(edge){if(edge.kind==='match'&&!selectedEdge.value)return .72;if(!selection.value)return view.value==='market'&&expand.value?(edge.kind==='membership'?.22:.12):edge.kind==='data'?.3:.65;return selectedEdge.value?edge.id===selection.value?1:.06:edge.source===selection.value||edge.target===selection.value?1:.06}
function nodeOpacity(node){if(!selection.value)return 1;if(selectedEdge.value)return [selectedEdge.value.source,selectedEdge.value.target].includes(node.id)?1:.32;return node.id===selection.value||connections.value.some(edge=>edge.source===node.id||edge.target===node.id)?1:.35}
watch([view,expand,showData],()=>{if(!selectedNode.value&&!selectedEdge.value)selection.value=''})
watch(()=>props.initiallyCollapsed,value=>{if(!value)collapsed.value=false})
watch(traderRound,()=>{selection.value=dialogue.value?.participants?.[0]?.id||''})
watch([view,expand,()=>population.value?.status],()=>{if(view.value==='market'&&expand.value&&!selection.value)selection.value=defaultTrader()},{immediate:true})
watch([view,()=>dialogue.value?.participant_count],()=>{if(view.value==='traders'&&!selection.value)selection.value=dialogue.value?.participants?.[0]?.id||''},{immediate:true})
watch(()=>dialogue.value?.participant_count,(count,old)=>{if(count&&!old&&!viewChosen&&isPendingAnalysis(props.run.status)){view.value='traders';selection.value=dialogue.value.participants[0]?.id||''}})
watch(selection,()=>{const node=selectedNode.value;if(node)focusId.value=['trader','provider'].includes(node.type)?node.id:'';else if(!selectedEdge.value)focusId.value=''},{immediate:true})
watch(selectedCase,()=>{if(selection.value.startsWith('match:'))selection.value=focusId.value})
async function fetchMatches(){
  const request=++matchRequest;matchController?.abort();matches.value=null;matchError.value='';matchesLoading.value=false
  if(view.value!=='market'||!expand.value||marketMode.value!=='counterparties'||!focusId.value||population.value?.status!=='complete')return
  const key=[props.run.id,selectedCase.value,focusId.value].join('/')
  if(matchCache.has(key)){matches.value=matchCache.get(key);return}
  matchController=new AbortController();matchesLoading.value=true
  try{const response=await apiFetch(`${api}/api/chart/analyses/${props.run.id}/participant-interactions/${selectedCase.value}/${encodeURIComponent(focusId.value)}`,{signal:matchController.signal});const body=await response.json();if(!response.ok||body.success===false)throw new Error(body.error||'Could not load matches.');if(request!==matchRequest)return;matches.value=body.interactions;matchCache.set(key,body.interactions)}
  catch(error){if(request===matchRequest&&error.name!=='AbortError')matchError.value=error.message}
  finally{if(request===matchRequest)matchesLoading.value=false}
}
watch([view,expand,marketMode,focusId,selectedCase,()=>props.run.id,()=>population.value?.status],fetchMatches,{immediate:true})
onBeforeUnmount(()=>{matchRequest++;matchController?.abort()})
</script>

